import argparse
import json
from pathlib import Path

DB = Path(__file__).with_name('records.json')


def load():
    return json.loads(DB.read_text())


def list_records():
    return [record for record in load() if not record.get('removed', False)]


def remove_record(record_id):
    records = load()
    for record in records:
        if record['id'] == record_id:
            if not record.get('removed', False):
                record['removed'] = True
                DB.write_text(json.dumps(records) + '\n')
            return
    raise ValueError(f'Record {record_id} not found')


def main():
    parser = argparse.ArgumentParser()
    commands = parser.add_subparsers(dest='command', required=True)
    commands.add_parser('list')
    remove = commands.add_parser('remove')
    remove.add_argument('id', type=int)
    args = parser.parse_args()
    if args.command == 'list':
        print(json.dumps(list_records()))
    else:
        try:
            remove_record(args.id)
        except ValueError as error:
            parser.exit(1, f'{error}\n')
        print(f'Record {args.id} removed')


if __name__ == '__main__':
    main()
